class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def tree_width(root):
    if root is None:
        return 0
    queue = [root]
    best = 0
    while queue:
        level_size = len(queue)
        if level_size > best:
            best = level_size
        for _ in range(level_size):
            node = queue.pop(0)
            if node.left is not None:
                queue.append(node.left)
            if node.right is not None:
                queue.append(node.right)
    return best

tree = TreeNode(1, TreeNode(2, TreeNode(4), TreeNode(5)), TreeNode(3, TreeNode(6), TreeNode(7)))
print(tree_width(tree))
print(tree_width(None))
print(tree_width(TreeNode(1)))
print(tree_width(TreeNode(1, TreeNode(2, TreeNode(4)), TreeNode(3))))
